<?php
session_start();
require '../../includes/conexao.php';
require '../../includes/verificar_sessao.php';
verificar_perfil('Secretaria');
$id = intval($_GET['id'] ?? $_POST['id'] ?? 0);
$mensagem = '';
$vinculos = [];
$result = $conexao->query('SELECT td.id_turma_disciplina,t.nome AS turma_nome,d.nome AS disciplina_nome,u.nome AS professor_nome FROM turma_disciplina td JOIN turma t ON t.id_turma=td.id_turma JOIN disciplina d ON d.id_disciplina=td.id_disciplina JOIN usuario u ON u.id_usuario=td.id_professor ORDER BY t.nome,d.nome');
while ($row=$result->fetch_assoc()) { $vinculos[]=$row; }
if ($_SERVER['REQUEST_METHOD']==='POST') {
    if (isset($_POST['excluir'])) {
        $stmt = $conexao->prepare('DELETE FROM horario WHERE id_horario=?');
        $stmt->bind_param('i', $id);
        $ok = $stmt->execute();
        $stmt->close();
        $mensagem = $ok ? '<div class="sucesso">Horário excluído com sucesso.</div>' : '<div class="erro">Não foi possível excluir o horário.</div>';
        $id = 0;
    }
    $vinculo=intval($_POST['id_turma_disciplina']??0);$dia=$_POST['dia_semana']??'';$inicio=$_POST['hora_inicio']??'';$fim=$_POST['hora_fim']??'';
    if(!isset($_POST['excluir'])&&$id>0&&$vinculo>0&&in_array($dia,['Segunda','Terça','Quarta','Quinta','Sexta'],true)&&$inicio!==''&&$fim!==''){$stmt=$conexao->prepare('UPDATE horario SET id_turma_disciplina=?,dia_semana=?,hora_inicio=?,hora_fim=? WHERE id_horario=?');$stmt->bind_param('isssi',$vinculo,$dia,$inicio,$fim,$id);$ok=$stmt->execute();$stmt->close();$mensagem=$ok?'<div class="sucesso">Horário atualizado com sucesso.</div>':'<div class="erro">Não foi possível atualizar o horário.</div>';}
}
$horarios=[];$result=$conexao->query("SELECT h.id_horario,h.id_turma_disciplina,h.dia_semana,h.hora_inicio,h.hora_fim,t.nome AS turma_nome,d.nome AS disciplina_nome,u.nome AS professor_nome FROM horario h JOIN turma_disciplina td ON td.id_turma_disciplina=h.id_turma_disciplina JOIN turma t ON t.id_turma=td.id_turma JOIN disciplina d ON d.id_disciplina=td.id_disciplina JOIN usuario u ON u.id_usuario=td.id_professor ORDER BY t.nome,h.dia_semana,h.hora_inicio");while($row=$result->fetch_assoc()){$horarios[]=$row;}
$registro=null;if($id>0){$stmt=$conexao->prepare('SELECT * FROM horario WHERE id_horario=?');$stmt->bind_param('i',$id);$stmt->execute();$registro=$stmt->get_result()->fetch_assoc();$stmt->close();}
?>
<!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Secretaria | Editar horários</title><style>*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#f3f6fb;color:#1f2937}main{max-width:1100px;margin:32px auto;padding:0 20px 40px}.header{background:linear-gradient(135deg,#0d3d70,#1b8ac0);color:#fff;border-radius:18px;padding:26px 28px;margin-bottom:24px}.header h1{margin:0;font-size:2rem}.panel{background:#fff;border:1px solid #e2eaf5;border-radius:18px;padding:22px;margin-bottom:20px;box-shadow:0 8px 20px rgba(15,23,42,.04)}.form{display:flex;gap:12px;flex-wrap:wrap;align-items:end}.campo{display:flex;flex-direction:column;gap:6px;min-width:190px}.campo label{font-size:.78rem;font-weight:bold;color:#45556b}.campo select,.campo input{padding:9px;border:1px solid #dfe8f4;border-radius:8px;background:#f9fbff}.btn,.editar,.remover{border:0;border-radius:8px;padding:9px 13px;font-weight:bold;cursor:pointer}.btn{background:#0d4a8f;color:#fff}.editar{background:#eaf3ff;color:#0b447d;text-decoration:none}.remover{background:#fbe9ea;color:#b3262f}.tabela{width:100%;border-collapse:collapse}.tabela th,.tabela td{padding:11px;border-bottom:1px solid #edf2f9;text-align:left;font-size:.85rem}.tabela th{font-size:.72rem;color:#6b7280;text-transform:uppercase}.sucesso,.erro{padding:10px 12px;border-radius:8px;margin-bottom:15px}.sucesso{background:#eaf7ee;color:#1d6f3b}.erro{background:#fee;color:#9d1c1c}</style></head><body><?php include '../../includes/menu_secretaria.php';?><main><section class="header"><h1>Gerenciar horários</h1></section><?php echo $mensagem;?><?php if($registro):?><section class="panel"><h2>Alterar horário</h2><form class="form" method="POST"><input type="hidden" name="id" value="<?php echo $id;?>"><div class="campo"><label>Turma, disciplina e professor</label><select name="id_turma_disciplina" required><?php foreach($vinculos as $item):?><option value="<?php echo $item['id_turma_disciplina'];?>" <?php echo $registro['id_turma_disciplina']==$item['id_turma_disciplina']?'selected':'';?>><?php echo htmlspecialchars($item['turma_nome'].' - '.$item['disciplina_nome'].' - '.$item['professor_nome']);?></option><?php endforeach;?></select></div><div class="campo"><label>Dia</label><select name="dia_semana"><option <?php echo $registro['dia_semana']==='Segunda'?'selected':'';?>>Segunda</option><option <?php echo $registro['dia_semana']==='Terça'?'selected':'';?>>Terça</option><option <?php echo $registro['dia_semana']==='Quarta'?'selected':'';?>>Quarta</option><option <?php echo $registro['dia_semana']==='Quinta'?'selected':'';?>>Quinta</option><option <?php echo $registro['dia_semana']==='Sexta'?'selected':'';?>>Sexta</option></select></div><div class="campo"><label>Início</label><input type="time" name="hora_inicio" value="<?php echo htmlspecialchars(substr($registro['hora_inicio'],0,5));?>" required></div><div class="campo"><label>Fim</label><input type="time" name="hora_fim" value="<?php echo htmlspecialchars(substr($registro['hora_fim'],0,5));?>" required></div><button class="btn">Salvar</button><a class="editar" href="editar_horario_secretaria.php">Cancelar</a></form></section><?php endif;?><section class="panel"><h2>Horários cadastrados</h2><table class="tabela"><tr><th>Turma</th><th>Disciplina</th><th>Professor</th><th>Dia</th><th>Horário</th><th>Ações</th></tr><?php foreach($horarios as $item):?><tr><td><?php echo htmlspecialchars($item['turma_nome']);?></td><td><?php echo htmlspecialchars($item['disciplina_nome']);?></td><td><?php echo htmlspecialchars($item['professor_nome']);?></td><td><?php echo htmlspecialchars($item['dia_semana']);?></td><td><?php echo htmlspecialchars(substr($item['hora_inicio'],0,5).' - '.substr($item['hora_fim'],0,5));?></td><td><a class="editar" href="?id=<?php echo $item['id_horario'];?>">Editar</a> <form method="POST" style="display:inline" onsubmit="return confirm('Excluir este horário?');"><input type="hidden" name="id" value="<?php echo $item['id_horario'];?>"><input type="hidden" name="excluir" value="1"><button class="remover">Excluir</button></form></td></tr><?php endforeach;?></table></section></main></body></html>
